# ---------------------------------------------------------------- helpers

def wrap(draw, text, fnt, width):
    """Greedy word wrap to a pixel width; returns list of lines."""
    words, lines, cur = text.split(), [], ""
    for w in words:
        t = (cur + " " + w).strip()
        if draw.textlength(t, font=fnt) <= width:
            cur = t
        else:
            if cur:
                lines.append(cur)
            cur = w
    if cur:
        lines.append(cur)
    return lines


def fit_font(draw, text, fname, size, width):
    """Largest font size <= size that fits text in width (min 8)."""
    s = size
    while s > 8 and draw.textlength(text, font=font(fname, s)) > width:
        s -= 1
    return font(fname, s)


def label_chip(d, x, y, label):
    """Small outlined label chip with a solid paper fill so it stays
    readable over illustration art; returns its width."""
    f = SANS_B(8)
    w = int(d.textlength(label, font=f)) + 10
    col = {"CONFIRMED": GREEN, "OFFICIAL": BLUE, "REPORTED": GOLD,
           "CLAIM": RED, "FORECAST": PURPLE}.get(label, GREY)
    d.rounded_rectangle([x, y, x + w, y + 11], radius=3, outline=col, width=1,
                        fill=CARD)
    d.text((x + 5, y + 1), label, font=f, fill=col)
    return w


def header_chip(d, x, y, text, col):
    """Solid-colour chip with white text, over illustration art."""
    f = SANS_B(9)
    w = int(d.textlength(text, font=f)) + 10
    d.rounded_rectangle([x, y, x + w, y + 13], radius=3, fill=col)
    d.text((x + 5, y + 1), text, font=f, fill=(255, 255, 255))
    return w


def fit_headline(draw, text, width):
    """Largest serif-bold size 11..9 whose wrap is at most two lines."""
    for s in (11, 10, 9):
        if len(wrap(draw, text, SERIF_B(s), width)) <= 2:
            return SERIF_B(s)
    return SERIF_B(9)


def star_points(cx, cy, R, r=None, rot=-90):
    """Five-pointed star polygon points (rot in degrees, -90 = point up)."""
    if r is None:
        r = R * 0.42
    pts = []
    for i in range(10):
        ang = math.radians(rot + i * 36)
        rr = R if i % 2 == 0 else r
        pts.append((cx + rr * math.cos(ang), cy + rr * math.sin(ang)))
    return pts


def vgrad(d, x, y, w, h, top, bot):
    """Deterministic vertical gradient: 1-px strips from the top colour
    to the bottom colour. Gives skies, seas, metal and wood a lit,
    realistic depth instead of flat fills."""
    if h <= 1:
        d.rectangle([x, y, x + w, y + h], fill=top)
        return
    for yy in range(h):
        t = yy / (h - 1)
        d.line([x, y + yy, x + w, y + yy],
               fill=tuple(int(top[i] + (bot[i] - top[i]) * t)
                          for i in range(3)))


