# Map projection: equirectangular with ONE scale for both axes
# (px per degree is identical for longitude and latitude), so every
# continent keeps its true proportions — Africa larger than Europe,
# South America and Australia recognisable, Greenland not exaggerated.
# The shown window is lon -170..180, lat 78..-50; MAP_S is set from
# the map width in main().
MAP_LON0, MAP_LAT_TOP = -170.0, 78.0
MAP_S = 1.0  # px per degree; set in main() from the map box width


def project(lon, lat, x0, y0, w, h):
    """Equal-scale equirectangular projection into the map box."""
    px = x0 + (lon - MAP_LON0) * MAP_S
    py = y0 + (MAP_LAT_TOP - lat) * MAP_S
    return px, py

# ---------------------------------------------------------------- illustrations
# Every illustration is drawn from scratch with vector shapes. `big` is
# True in the hero slots (wide box, caption line) and False in the small
# feature slots.

def illus_cop31(d, x, y, w, h, big):
    cx, cy = x + w // 2, y + h // 2
    # conference-room wall: soft daylight gradient, warmer near the table
    vgrad(d, x, y, w, h, (233, 239, 243), (216, 224, 232))
    d.line([x, y + h - 11, x + w, y + h - 11], fill=(190, 198, 208), width=1)
    # desk globe, with spherical shading, continents, meridians and a
    # stand, so it reads as a real globe on the table, not a flat disc
    r = h // 2 - 10 if big else min(w, h) // 2 - 2
    gx = cx - (w // 6 if big else 0)
    gy = cy - 6 if big else cy - 2
    d.ellipse([gx - r, gy - r, gx + r, gy + r], fill=(150, 200, 228),
              outline=TEAL, width=2)
    d.ellipse([gx - r + 3, gy - r + 2, gx + r - 1, gy + r - 2],
              fill=(170, 212, 236))
    d.ellipse([gx - r + 5, gy - r + 7, gx - 4, gy - 2], fill=(110, 165, 105))
    d.ellipse([gx + 2, gy + 2, gx + r - 5, gy + r - 7], fill=(125, 175, 110))
    d.ellipse([gx - r + 8, gy + r - 12, gx + 2, gy + r - 4], fill=(140, 185, 125))
    # shading crescent on the lower right, highlight arc upper left
    d.pieslice([gx - r, gy - r, gx + r, gy + r], -50, 110,
               fill=(120, 175, 205))
    d.arc([gx - r + 2, gy - r + 2, gx + r - 6, gy + r - 6], 180, 300,
          fill=(235, 245, 250), width=2)
    d.line([gx - r, gy, gx + r, gy], fill=TEAL, width=1)
    d.arc([gx - r // 2, gy - r, gx + r // 2, gy + r], 270, 90, fill=TEAL, width=1)
    d.arc([gx - r, gy - r // 2, gx + r, gy + r // 2], 180, 360, fill=TEAL,
          width=1)
    # globe stand: stem + base sitting on the table
    d.line([gx, gy + r, gx, y + h - 11], fill=(90, 80, 70), width=2)
    d.ellipse([gx - 5, y + h - 12, gx + 5, y + h - 9], fill=(90, 80, 70))
    # thermometer with a shaded red column and tick marks
    tx = x + w - 20
    d.rounded_rectangle([tx, y + 6, tx + 9, y + h - 18], radius=4,
                        fill=(255, 255, 255), outline=RED, width=2)
    d.rectangle([tx + 2, y + 16, tx + 7, y + h - 20], fill=(200, 30, 30))
    d.rectangle([tx + 4, y + 16, tx + 5, y + h - 20], fill=(255, 120, 110))
    d.ellipse([tx - 3, y + h - 26, tx + 12, y + h - 11], fill=(200, 30, 30))
    d.ellipse([tx - 1, y + h - 24, tx + 4, y + h - 19], fill=(255, 150, 140))
    for ty in (y + 12, y + 22, y + 32):
        d.line([tx - 3, ty, tx, ty], fill=RED, width=1)
    # day counter
    if big:
        # Compact negotiation scene that fits the 38 px band: a small
        # DAY 13 box top-left, the globe, three delegates behind a table
        # along the bottom, and the DRAFT 3 paper leaning on the table
        # below the DAY 13 box, so the two never collide. Delegates now
        # have skin tones, hair, shirts with collars, and the table is
        # shaded wood with papers and a glass on it.
        d.rectangle([x + 4, y + 4, x + 44, y + 16], fill=RED)
        d.text((x + 24, y + 5), "DAY 13", font=SANS_B(9), fill=(255, 255, 255),
               anchor="ma")
        skins = [(215, 175, 135), (190, 145, 105), (225, 185, 150)]
        shirts = [(40, 70, 120), (130, 40, 45), (30, 100, 90)]
        for k, dx in enumerate((0.45, 0.62, 0.79)):
            hx = x + int(w * dx)
            # head with hair, shoulders in a shirt with a white collar
            d.ellipse([hx - 4, y + h - 23, hx + 4, y + h - 15],
                      fill=skins[k])
            d.pieslice([hx - 4, y + h - 23, hx + 4, y + h - 15], 180, 360,
                       fill=(45, 40, 35))
            d.polygon([(hx - 7, y + h - 16), (hx + 7, y + h - 16),
                       (hx + 5, y + h - 9), (hx - 5, y + h - 9)],
                      fill=shirts[k])
            d.polygon([(hx - 2, y + h - 16), (hx + 2, y + h - 16),
                       (hx, y + h - 12)], fill=(245, 245, 240))
            if k == 1:
                d.polygon([(hx - 1, y + h - 13), (hx + 1, y + h - 13),
                           (hx, y + h - 9)], fill=(30, 30, 30))
        # shaded wood table: dark top edge, lighter front, highlight line
        d.rectangle([x + 4, y + h - 10, x + w - 28, y + h - 2],
                    fill=(150, 110, 70))
        d.rectangle([x + 4, y + h - 10, x + w - 28, y + h - 8],
                    fill=(120, 85, 50))
        d.line([x + 4, y + h - 9, x + w - 28, y + h - 9],
               fill=(190, 150, 100), width=1)
        # papers and a water glass on the table
        d.rectangle([x + 90, y + h - 10, x + 104, y + h - 8],
                    fill=(250, 250, 245))
        d.rectangle([x + 208, y + h - 10, x + 220, y + h - 8],
                    fill=(250, 250, 245))
        d.rectangle([x + w - 44, y + h - 10, x + w - 40, y + h - 8],
                    fill=(200, 225, 240), outline=(150, 180, 200), width=1)
        # DRAFT 3 paper with a soft shadow, leaning on the table
        d.rectangle([x + 7, y + h - 19, x + 41, y + h - 10],
                    fill=(220, 215, 200))
        d.rectangle([x + 6, y + h - 20, x + 40, y + h - 11],
                    fill=(255, 255, 255), outline=INK, width=1)
        d.text((x + 23, y + h - 19), "DRAFT 3", font=SANS_B(6), fill=RED,
               anchor="ma")


def illus_missiles(d, x, y, w, h, big):
    cx, cy = x + w // 2, y + h // 2
    # night sky: deep navy fading to a dusk-purple horizon glow
    vgrad(d, x, y, w, h, (16, 24, 58), (58, 48, 98))
    rng = random.Random(21)
    for _ in range(40 if big else 10):
        sx = x + rng.randint(2, w - 3)
        sy = y + rng.randint(2, h // 2)
        sz = rng.choice((1, 1, 1, 2))
        scol = rng.choice([(255, 240, 180), (220, 230, 255),
                           (255, 255, 255), (190, 200, 230)])
        d.ellipse([sx, sy, sx + sz, sy + sz], fill=scol)
    # a few bright four-point star glints
    for (gx2, gy2) in ((x + 30, y + 6), (x + w // 2 - 8, y + 4),
                       (x + w - 60, y + 8)):
        d.line([gx2 - 3, gy2, gx2 + 3, gy2], fill=(255, 250, 210), width=1)
        d.line([gx2, gy2 - 3, gx2, gy2 + 3], fill=(255, 250, 210), width=1)
    # crescent moon with a soft halo and crater dots
    mx, my = x + w - 24, y + 12
    for rr, col in ((14, (48, 56, 100)), (11, (64, 72, 118))):
        d.ellipse([mx - rr, my - rr, mx + rr, my + rr], fill=col)
    d.ellipse([mx - 8, my - 8, mx + 8, my + 8], fill=(255, 240, 180))
    d.ellipse([mx - 3, my - 10, mx + 11, my + 6], fill=(30, 33, 72))
    for (ccx, ccy, cr) in ((mx - 4, my - 3, 2), (mx - 1, my + 4, 1)):
        d.ellipse([ccx - cr, ccy - cr, ccx + cr, ccy + cr],
                  fill=(230, 210, 150))
    # city skyline: a darker distant row for depth, then a nearer row
    # with lit windows in warm and cool tones, an antenna and a beacon
    base = y + h - 12
    for i, bh in enumerate((8, 14, 10, 18, 12)):
        bx = x + 10 + i * (w - 20) // 5
        bw = (w - 20) // 5 - 4
        d.rectangle([bx, base - bh, bx + bw, base], fill=(38, 44, 72))
    for i, bh in enumerate((14, 26, 18, 32, 22, 16)):
        bx = x + 4 + i * (w - 8) // 6
        bw = (w - 8) // 6 - 3
        d.rectangle([bx, base - bh, bx + bw, base], fill=(58, 63, 92))
        d.rectangle([bx, base - bh, bx + bw, base - bh + 2],
                    fill=(85, 90, 120))
        for wy in range(base - bh + 3, base - 2, 6):
            wcol = rng.choice([(255, 220, 120), (255, 220, 120),
                               (200, 225, 255), (70, 75, 105)])
            d.rectangle([bx + 2, wy, bx + 4, wy + 2], fill=wcol)
        if i == 3:
            d.line([bx + bw // 2, base - bh - 5, bx + bw // 2, base - bh],
                   fill=(90, 95, 125), width=1)
            d.ellipse([bx + bw // 2 - 1, base - bh - 7, bx + bw // 2 + 1,
                       base - bh - 5], fill=(255, 80, 80))
    # shield dome: a faint wide arc behind a brighter inner arc
    d.arc([x + 6, y + 4, x + w - 6, y + h + 6], 180, 360, fill=(110, 165, 225),
          width=3)
    d.arc([x + 6, y + 4, x + w - 6, y + h + 6], 180, 360, fill=(150, 205, 255),
          width=1)
    d.arc([x + 14, y + 10, x + w - 14, y + h + 2], 180, 360,
          fill=(150, 205, 255), width=1)
    # three missiles: layered flame trails, a shaded rocket body with a
    # red nose, and a burst with a hot core, sparks and drifting smoke
    for i, mx in enumerate((0.22, 0.5, 0.78)):
        tx = x + int(w * mx)
        ty = y + 12 + i * 4
        d.line([tx - 14, ty + 16, tx, ty], fill=(255, 140, 40), width=5)
        d.line([tx - 14, ty + 16, tx, ty], fill=(255, 200, 90), width=3)
        d.line([tx - 14, ty + 16, tx, ty], fill=(255, 250, 200), width=1)
        d.polygon([(tx, ty - 5), (tx + 4, ty + 2), (tx + 2, ty + 5),
                   (tx - 2, ty + 5), (tx - 4, ty + 2)], fill=(220, 220, 225))
        d.polygon([(tx, ty - 5), (tx + 2, ty - 1), (tx - 2, ty - 1)],
                  fill=RED)
        bx2, by2 = tx - 20, ty + 22
        for rr, col in ((10, (255, 150, 50)), (7, (255, 210, 100)),
                        (4, (255, 240, 180)), (2, (255, 255, 230))):
            d.ellipse([bx2 - rr, by2 - rr, bx2 + rr, by2 + rr], fill=col)
        for a in range(0, 360, 45):
            rr = math.radians(a)
            ln = 7 + (a % 90) // 45 * 3
            d.line([bx2, by2, bx2 + ln * math.cos(rr),
                    by2 + ln * math.sin(rr)], fill=(255, 170, 60), width=2)
        for (sx2, sy2, sr) in ((bx2 - 14, by2 + 6, 2), (bx2 - 18, by2 + 2, 1)):
            d.ellipse([sx2 - sr, sy2 - sr, sx2 + sr, sy2 + sr],
                      fill=(150, 150, 160))


def illus_quake(d, x, y, w, h, big):
    cx, cy = x + w // 2, y + h // 2
    # warm Andean sky with a soft sun glow, and a hazy far ridge
    vgrad(d, x, y, w, h, (238, 228, 200), (222, 208, 175))
    d.ellipse([x + w - 30, y - 6, x + w - 6, y + 18], fill=(245, 238, 210))
    d.ellipse([x + w - 24, y - 2, x + w - 12, y + 12], fill=(250, 244, 220))
    d.polygon([(x, y + h), (x + w * 0.25, y + 16), (x + w * 0.5, y + h)],
              fill=(175, 165, 145))
    d.polygon([(x + w * 0.45, y + h), (x + w * 0.7, y + 12),
               (x + w * 0.95, y + h)], fill=(175, 165, 145))
    # Andes: each peak has a sunlit face, a shadow face and a shaded
    # snowcap, so the range reads as real mountains, not flat triangles
    d.polygon([(x, y + h), (x + w * 0.18, y + 10), (x + w * 0.38, y + h)],
              fill=(150, 140, 120))
    d.polygon([(x + w * 0.18, y + 10), (x + w * 0.28, y + h),
               (x + w * 0.38, y + h)], fill=(125, 115, 98))
    d.polygon([(x + w * 0.3, y + h), (x + w * 0.55, y + 4), (x + w * 0.8, y + h)],
              fill=(120, 110, 95))
    d.polygon([(x + w * 0.55, y + 4), (x + w * 0.68, y + h),
               (x + w * 0.8, y + h)], fill=(100, 92, 80))
    d.polygon([(x + w * 0.62, y + h), (x + w * 0.85, y + 14), (x + w, y + h)],
              fill=(150, 140, 120))
    d.polygon([(x + w * 0.85, y + 14), (x + w * 0.93, y + h), (x + w, y + h)],
              fill=(125, 115, 98))
    d.polygon([(x + w * 0.5, y + 4), (x + w * 0.55, y + 4), (x + w * 0.58, y + 14),
               (x + w * 0.52, y + 14)], fill=(255, 255, 255))
    d.polygon([(x + w * 0.55, y + 4), (x + w * 0.58, y + 14),
               (x + w * 0.56, y + 14)], fill=(215, 225, 235))
    d.polygon([(x + w * 0.15, y + 10), (x + w * 0.18, y + 10),
               (x + w * 0.2, y + 17), (x + w * 0.16, y + 17)],
              fill=(255, 255, 255))
    # shaking buildings: varied colours, lit and dark windows, roof
    # highlights, base shadows, and a crack zigzag on one of them
    base = y + h - 10
    blds = ((4, 12, 20, -2), (20, 12, 28, 2), (36, 14, 16, -3),
            (52, 12, 24, 2), (68, 14, 20, -2), (84, 12, 26, 3)) if big else \
           ((6, 16, 22, -2), (26, 14, 30, 2), (46, 18, 18, -3), (68, 14, 26, 2))
    bcols = [(95, 85, 70), (110, 90, 70), (85, 80, 75),
             (120, 100, 80), (90, 85, 70), (105, 95, 85)]
    for i, (bx, bw, bh, tilt) in enumerate(blds):
        px = x + bx * w // 100
        pw = bw * w // 100
        ph = bh * h // 100
        d.ellipse([px - 1, base - 2, px + pw + 1, base + 2], fill=(100, 90, 75))
        d.polygon([(px, base), (px + tilt, base - ph), (px + pw + tilt, base - ph),
                   (px + pw, base)], fill=bcols[i % len(bcols)])
        d.line([px + tilt, base - ph, px + pw + tilt, base - ph],
               fill=(200, 190, 170), width=1)
        for wy in range(base - ph + 4, base - 3, 7):
            wcol = (255, 220, 120) if (i + wy) % 3 else (60, 55, 50)
            d.rectangle([px + 3, wy, px + 6, wy + 3], fill=wcol)
        if i == 2:
            d.line([px + pw // 2, base - ph + 2, px + pw // 2 + 2,
                    base - ph + 8, px + pw // 2 - 1, base - ph + 12],
                   fill=(50, 45, 40), width=1)
    # ground crack with a lit raised edge, for depth
    d.line([x + 4, base, x + w * 0.3, base + 4, x + w * 0.55, base - 2,
            x + w - 4, base + 3], fill=INK, width=2)
    d.line([x + 4, base + 2, x + w * 0.3, base + 6, x + w * 0.55, base,
            x + w - 4, base + 5], fill=(200, 190, 165), width=1)
    if big:
        # seismograph strip with a faint grid and a waveform whose
        # spikes swell in the middle, like a real 6.7 reading
        d.rectangle([x + 8, y + 5, x + w - 8, y + 17], fill=(255, 255, 255),
                    outline=RED, width=1)
        for gx2 in range(x + 28, x + w - 12, 20):
            d.line([gx2, y + 6, gx2, y + 16], fill=(235, 235, 235), width=1)
        d.line([x + 8, y + 11, x + w - 8, y + 11], fill=(235, 235, 235),
               width=1)
        srng = random.Random(6)
        spts = []
        sx = x + 12
        n = 0
        while sx < x + w - 32:
            t = (sx - x - 12) / max(1, w - 44)
            amp = 1 + 4 * math.sin(math.pi * t)
            spts.append((sx, y + 11 + int(srng.uniform(-amp, amp))))
            sx += 4
            n += 1
        d.line([(px2, py2 + 1) for (px2, py2) in spts], fill=(180, 30, 30),
               width=1)
        d.line(spts, fill=RED, width=1)
        d.text((x + w - 12, y + 6), "6.7", font=SANS_B(8), fill=RED,
               anchor="ra")
        # dust puffs at the building bases: layered, soft-edged
        for (dx, dy, dr) in ((0.15, 0.82, 5), (0.45, 0.86, 6), (0.75, 0.82, 5)):
            cx2, cy2 = x + int(w * dx), y + int(h * dy)
            d.ellipse([cx2 - dr, cy2 - dr // 2, cx2 + dr, cy2 + dr // 2],
                      fill=(190, 180, 160))
            d.ellipse([cx2 - dr + 2, cy2 - dr // 2 + 1, cx2 + dr - 1,
                       cy2 + dr // 2], fill=(215, 205, 185))
            d.ellipse([cx2 - dr // 2, cy2 - dr // 3, cx2 + dr // 2,
                       cy2 + dr // 3], fill=(232, 224, 205))


def illus_davao(d, x, y, w, h, big):
    cx, cy = x + w // 2, y + h // 2
    # sky gradient, sun with a glow, and soft shaded clouds
    vgrad(d, x, y, w, h, (185, 218, 240), (228, 240, 248))
    for rr, col in ((16, (255, 235, 170)), (12, (255, 240, 190))):
        d.ellipse([x + w - 24 - rr, y + 12 - rr, x + w - 24 + rr,
                   y + 12 + rr], fill=col)
    d.ellipse([x + w - 24, y + 4, x + w - 8, y + 20], fill=(255, 220, 100),
              outline=GOLD, width=2)
    d.ellipse([x + w - 22, y + 6, x + w - 16, y + 12], fill=(255, 240, 180))
    for (ccx, ccy, cr) in ((x + 22, y + 8, 7), (x + 66, y + 5, 6),
                           (x + w - 70, y + 30, 6)):
        d.ellipse([ccx - cr, ccy - cr // 2, ccx + cr, ccy + cr // 2],
                  fill=(255, 255, 255))
        d.ellipse([ccx - cr, ccy, ccx + cr, ccy + cr // 2],
                  fill=(210, 225, 235))
    # grass strip below the runway, for the ground to read
    base = y + h - 12
    d.rectangle([x, base + 4, x + w, y + h], fill=(150, 190, 120))
    d.line([x, base + 4, x + w, base + 4], fill=(120, 165, 95), width=1)
    # runway with edge lines and centre dashes
    d.rectangle([x, base, x + w, base + 4], fill=(70, 70, 70))
    d.line([x, base, x + w, base], fill=(200, 200, 200), width=1)
    for dx in range(6, w - 6, 14):
        d.line([x + dx, base + 2, x + dx + 7, base + 2], fill=(255, 255, 255),
               width=1)
    # plane: shaded fuselage (bright top, grey-blue belly), a red
    # cheatline, cockpit panes with glints, a red tail fin, shaded wings
    py = cy - 4
    d.polygon([(x + 6, py), (x + w - 22, py - 8), (x + w - 8, py - 2),
               (x + w - 22, py + 6), (x + 6, py + 6)], fill=(245, 245, 245),
              outline=INK, width=2)
    d.polygon([(x + 8, py + 3), (x + w - 22, py + 3), (x + w - 22, py + 6),
               (x + 6, py + 6)], fill=(205, 215, 225))
    d.line([x + 8, py - 5, x + w - 24, py - 7], fill=(255, 255, 255), width=1)
    d.polygon([(x + 10, py - 1), (x + w - 26, py - 5), (x + w - 26, py - 3),
               (x + 10, py + 1)], fill=(200, 60, 50))
    # cockpit panes
    d.polygon([(x + w - 20, py - 7), (x + w - 12, py - 4), (x + w - 12, py - 1),
               (x + w - 20, py - 4)], fill=(40, 70, 110))
    d.polygon([(x + w - 19, py - 6), (x + w - 15, py - 5), (x + w - 15, py - 3),
               (x + w - 19, py - 4)], fill=(150, 200, 235))
    # tail fin in Air Niugini red with a gold bird-of-paradise mark
    d.polygon([(x + 12, py + 2), (x + 20, py - 18), (x + 28, py + 2)],
              fill=(200, 50, 40), outline=INK, width=1)
    d.polygon([(x + 18, py - 14), (x + 22, py - 14), (x + 20, py - 8)],
              fill=(255, 200, 60))
    # wings: upper wing with a shaded underside, lower wing below the body
    d.polygon([(x + w // 2, py - 6), (x + w // 2 + 12, py - 20),
               (x + w // 2 + 18, py - 6)], fill=(225, 232, 240), outline=INK, width=1)
    d.polygon([(x + w // 2 + 12, py - 20), (x + w // 2 + 18, py - 6),
               (x + w // 2 + 14, py - 6)], fill=(185, 195, 205))
    d.polygon([(x + 12, py + 4), (x + 22, py + 16), (x + 28, py + 4)],
              fill=(200, 210, 220), outline=INK, width=1)
    for wx in range(x + 14, x + w - 30, 9):
        d.rounded_rectangle([wx, py - 3, wx + 4, py], radius=1,
                            fill=(40, 70, 110))
        d.ellipse([wx, py - 3, wx + 1, py - 1], fill=(180, 215, 240))
    # right engine: metallic nacelle with a dark intake, and layered
    # smoke puffs drifting up and back
    ex, ey = x + w - 34, py + 8
    d.ellipse([ex, ey, ex + 10, ey + 6], fill=(120, 125, 130))
    d.ellipse([ex + 2, ey + 1, ex + 6, ey + 5], fill=(60, 60, 65))
    d.ellipse([ex + 3, ey + 2, ex + 5, ey + 4], fill=(30, 30, 35))
    for i, (sx, sy, sr) in enumerate(((ex + 12, ey - 6, 4), (ex + 20, ey - 12, 6),
                                      (ex + 30, ey - 18, 8))):
        d.ellipse([sx - sr, sy - sr, sx + sr, sy + sr], fill=(200, 200, 200),
                  outline=(160, 160, 160), width=1)
        d.ellipse([sx - sr + 1, sy - sr + 1, sx + sr - 2, sy + sr - 2],
                  fill=(225, 225, 225))
    # evacuation slide, shaded gold with side stripes, on the runway
    d.polygon([(x + w - 30, py + 6), (x + w - 14, py + 6), (x + w - 6, base),
               (x + w - 16, base)], fill=GOLD, outline=(150, 110, 10), width=1)
    d.polygon([(x + w - 26, py + 6), (x + w - 18, py + 6), (x + w - 10, base),
               (x + w - 14, base)], fill=(230, 180, 60))
    d.line([x + w - 28, py + 6, x + w - 14, base], fill=(255, 230, 140),
           width=1)


def illus_bitcoin(d, x, y, w, h, big):
    cx, cy = x + w // 2, y + h // 2
    # chart grid: faint horizontals and verticals, like a trading screen
    for gy in (y + 10, y + 22, y + 34):
        d.line([x + 6, gy, x + w - 8, gy], fill=(220, 212, 190), width=1)
    for gx2 in range(x + 30, x + w - 8, 24):
        d.line([gx2, y + 8, gx2, y + h - 16], fill=(232, 226, 208), width=1)
    # falling candles with shaded bodies, wicks and a soft shadow
    cw = 10 if big else 5
    vals = (12, 18, 14, 26, 22, 34) if big else (14, 24, 18, 32)
    for i, v in enumerate(vals):
        bx = x + 8 + i * (cw + 4) if big else x + 5 + i * (cw + 3)
        by = y + 10 + v * (h - 30) // 40
        d.rectangle([bx + 1, by + 1, bx + cw + 1, y + h - 15],
                    fill=(210, 200, 185))
        top = (225, 90, 80) if i % 2 else (205, 85, 75)
        bot = (180, 40, 35) if i % 2 else (165, 45, 40)
        vgrad(d, bx, by, cw, y + h - 16 - by, top, bot)
        d.line([bx + cw // 2, by - 4, bx + cw // 2, by], fill=INK, width=1)
        d.line([bx + cw // 2, y + h - 16, bx + cw // 2, y + h - 12],
               fill=INK, width=1)
    # volume bars along the bottom
    for i, v in enumerate(vals):
        bx = x + 8 + i * (cw + 4) if big else x + 5 + i * (cw + 3)
        vh = max(2, v // 6)
        d.rectangle([bx, y + h - 10 - vh, bx + cw, y + h - 10],
                    fill=(150, 160, 180))
    # metallic coin: dark rim, bright ring, reeded edge, a lit inner
    # disc and an embossed B with a cast shadow
    r = 20 if big else 13
    ccx = cx + (w // 4 if big else 0)
    ccy = cy - 4
    d.ellipse([ccx - r, ccy - r, ccx + r, ccy + r], fill=(150, 105, 10))
    d.ellipse([ccx - r + 2, ccy - r + 2, ccx + r - 2, ccy + r - 2],
              fill=(255, 205, 70))
    for a in range(0, 360, 15):
        rr = math.radians(a)
        d.line([ccx + (r - 2) * math.cos(rr), ccy + (r - 2) * math.sin(rr),
                ccx + (r - 5) * math.cos(rr), ccy + (r - 5) * math.sin(rr)],
               fill=(170, 120, 20), width=1)
    d.ellipse([ccx - r + 5, ccy - r + 5, ccx + r - 5, ccy + r - 5],
              fill=(245, 195, 80))
    d.ellipse([ccx - r + 5, ccy - r + 5, ccx + r - 8, ccy + r - 8],
              fill=(255, 220, 120))
    d.ellipse([ccx - r + 4, ccy - r + 4, ccx + r - 4, ccy + r - 4],
              outline=(200, 150, 30), width=1)
    d.arc([ccx - r + 3, ccy - r + 3, ccx + r - 3, ccy + r - 3], 200, 330,
          fill=(255, 240, 180), width=2)
    d.text((ccx + 1, ccy), "B", font=SANS_B(22 if big else 14),
           fill=(120, 80, 5), anchor="mm")
    d.text((ccx, ccy - 1), "B", font=SANS_B(22 if big else 14),
           fill=(160, 105, 15), anchor="mm")
    # down arrow with a layered shaft and a soft shadow
    d.line([x + w - 25, y + 9, x + w - 7, y + h - 21], fill=(180, 25, 25),
           width=4)
    d.line([x + w - 26, y + 8, x + w - 8, y + h - 22], fill=(240, 70, 60),
           width=2)
    d.polygon([(x + w - 8, y + h - 22), (x + w - 20, y + h - 24),
               (x + w - 10, y + h - 12)], fill=(200, 30, 30))
    d.polygon([(x + w - 9, y + h - 21), (x + w - 18, y + h - 23),
               (x + w - 11, y + h - 14)], fill=(240, 70, 60))


def illus_rahul(d, x, y, w, h, big):
    cx, cy = x + w // 2, y + h // 2
    # outfield with mowing stripes and a boundary rope, plus grass specks
    vgrad(d, x, y, w, h, (185, 215, 165), (165, 200, 145))
    for sy in range(y + 8, y + h - 4, 16):
        d.rectangle([x, sy, x + w, sy + 8], fill=(172, 206, 152))
    d.ellipse([x + 6, y + 6, x + w - 6, y + h - 6], outline=(150, 190, 130),
              width=2)
    grng = random.Random(9)
    for _ in range(24):
        px = x + grng.randint(4, w - 5)
        py = y + grng.randint(4, h - 5)
        d.point((px, py), fill=(150, 185, 130))
    # pitch: worn tan strip with creases and wear marks
    d.rectangle([cx - 12, y + 6, cx + 12, y + h - 8], fill=(235, 220, 175))
    d.ellipse([cx - 10, y + 20, cx + 10, y + 40], fill=(240, 228, 185))
    d.line([cx - 12, y + 10, cx + 12, y + 10], fill=(250, 248, 240), width=1)
    d.line([cx - 12, y + 50, cx + 12, y + 50], fill=(250, 248, 240), width=1)
    for (wx2, wy2, wr) in ((cx - 6, 28, 3), (cx + 5, 36, 2), (cx - 2, 46, 3)):
        d.ellipse([wx2 - wr, wy2 - wr // 2, wx2 + wr, wy2 + wr // 2],
                  fill=(220, 205, 160))
    # stumps with bails and a base shadow
    d.ellipse([cx - 10, y + h - 13, cx + 6, y + h - 10], fill=(200, 185, 145))
    for sx in (cx - 8, cx - 3, cx + 2):
        d.line([sx, y + h - 24, sx, y + h - 12], fill=GOLD, width=2)
        d.line([sx + 1, y + h - 24, sx + 1, y + h - 12], fill=(255, 230, 150),
               width=1)
    d.line([cx - 9, y + h - 25, cx + 4, y + h - 25], fill=GOLD, width=2)
    # batsman KL Rahul mid-follow-through: helmet, India-blue shirt,
    # white pads, bat raised toward the ball. He stands to the leg side
    # of the stumps, so the stumps stay visible on the off side.
    d.ellipse([cx - 20, y + 51, cx - 2, y + 55], fill=(140, 175, 125))
    # pads and shoes
    for px in (cx - 18, cx - 10):
        d.rectangle([px, y + 40, px + 6, y + 52], fill=(245, 245, 240),
                    outline=(200, 200, 195), width=1)
        d.line([px, y + 46, px + 6, y + 46], fill=(200, 200, 195), width=1)
        d.rectangle([px - 1, y + 52, px + 7, y + 54], fill=(40, 40, 45))
    # torso in India blue, leaning into the shot, white collar
    d.polygon([(cx - 18, y + 30), (cx - 4, y + 28), (cx - 2, y + 42),
               (cx - 18, y + 42)], fill=(35, 85, 175))
    d.polygon([(cx - 16, y + 30), (cx - 8, y + 29), (cx - 8, y + 36),
               (cx - 16, y + 37)], fill=(70, 125, 210))
    d.polygon([(cx - 12, y + 28), (cx - 8, y + 28), (cx - 10, y + 32)],
              fill=(245, 245, 240))
    # arms reaching forward to the bat handle, gloved hands
    d.line([cx - 4, y + 30, cx + 2, y + 22], fill=(35, 85, 175), width=3)
    d.ellipse([cx, y + 20, cx + 5, y + 25], fill=(30, 50, 100))
    # head with a navy helmet and grill
    d.ellipse([cx - 15, y + 15, cx - 5, y + 25], fill=(205, 165, 125))
    d.rectangle([cx - 12, y + 24, cx - 8, y + 29], fill=(205, 165, 125))
    d.pieslice([cx - 15, y + 15, cx - 5, y + 25], 180, 360,
               fill=(25, 55, 110))
    d.line([cx - 14, y + 21, cx - 6, y + 21], fill=(180, 180, 180), width=1)
    d.line([cx - 14, y + 23, cx - 6, y + 23], fill=(180, 180, 180), width=1)
    d.ellipse([cx - 12, y + 16, cx - 10, y + 18], fill=(255, 255, 255))
    # bat: dark grip, light wooden blade with a red sticker band
    d.line([cx + 2, y + 22, cx + 6, y + 16], fill=(60, 45, 30), width=3)
    d.line([cx + 6, y + 16, cx + 16, y + 8], fill=(215, 175, 115), width=5)
    d.line([cx + 6, y + 15, cx + 16, y + 7], fill=(235, 200, 140), width=2)
    d.line([cx + 12, y + 11, cx + 15, y + 9], fill=(200, 50, 40), width=2)
    # red ball with a seam, a highlight and a faint motion trail
    d.line([cx + 20, cy - 18, cx + 26, cy - 22], fill=(255, 255, 255), width=1)
    d.line([cx + 18, cy - 14, cx + 24, cy - 18], fill=(255, 200, 200), width=1)
    d.ellipse([cx + 14, cy - 20, cx + 22, cy - 12], fill=RED)
    d.ellipse([cx + 16, cy - 19, cx + 19, cy - 16], fill=(255, 150, 140))
    d.arc([cx + 14, cy - 20, cx + 22, cy - 12], 200, 340, fill=(255, 255, 255),
          width=1)
    # scoreboard (top-right: the number chip sits top-left)
    if big:
        d.rectangle([x + w - 66, y + 4, x + w - 4, y + 20], fill=INK)
        d.line([x + w - 66, y + 19, x + w - 4, y + 19], fill=GOLD, width=1)
        d.text((x + w - 35, y + 6), "136", font=SANS_B(12),
               fill=(255, 255, 255), anchor="ma")
    else:
        d.rectangle([x + 2, y + 2, x + 34, y + 14], fill=INK)
        d.text((x + 18, y + 3), "136", font=SANS_B(9), fill=(255, 255, 255),
               anchor="ma")


def illus_bepi(d, x, y, w, h, big):
    cx, cy = x + w // 2, y + h // 2
    rng = random.Random(77)
    # deep space with a subtle gradient and stars of varied brightness
    vgrad(d, x, y, w, h, (14, 18, 44), (30, 32, 68))
    for _ in range(30 if big else 12):
        sx = x + rng.randint(2, w - 3)
        sy = y + rng.randint(2, h - 3)
        sz = rng.choice((1, 1, 1, 2))
        scol = rng.choice([(255, 255, 255), (200, 220, 255),
                           (255, 240, 200), (180, 190, 220)])
        d.ellipse([sx, sy, sx + sz, sy + sz], fill=scol)
    for (gx2, gy2) in ((x + w - 30, y + 8), (x + 40, y + h - 12)):
        d.line([gx2 - 3, gy2, gx2 + 3, gy2], fill=(255, 255, 255), width=1)
        d.line([gx2, gy2 - 3, gx2, gy2 + 3], fill=(255, 255, 255), width=1)
    # sun with a layered glow and rays of varied length
    sx, sy = x + 12, y + 10
    for rr, col in ((18, (255, 190, 70)), (13, (255, 210, 100)),
                    (9, (255, 225, 130))):
        d.ellipse([sx - rr, sy - rr, sx + rr, sy + rr], fill=col)
    for a in range(0, 360, 30):
        rr = math.radians(a)
        ln = 12 + (a // 60 % 2) * 4
        d.line([sx, sy, sx + ln * math.cos(rr), sy + ln * math.sin(rr)],
               fill=(255, 200, 60), width=2)
    d.ellipse([sx - 6, sy - 6, sx + 6, sy + 6], fill=(255, 235, 150))
    d.ellipse([sx - 4, sy - 4, sx + 1, sy + 1], fill=(255, 250, 210))
    # Mercury: cratered grey-brown sphere with a terminator shadow on
    # the night side and a sunlit highlight
    mx, my = cx + w // 6, cy + h // 8
    mr = 16 if big else 10
    d.ellipse([mx - mr, my - mr, mx + mr, my + mr], fill=(175, 165, 155),
              outline=(120, 110, 100), width=2)
    d.ellipse([mx - mr + 2, my - mr + 2, mx + mr - 2, my + mr - 2],
              fill=(185, 175, 165))
    d.pieslice([mx - mr, my - mr, mx + mr, my + mr], -60, 60,
               fill=(140, 130, 120))
    for (ccx, ccy, cr) in ((mx - 5, my - 3, 3), (mx + 4, my + 2, 2),
                           (mx + 1, my - 7, 2), (mx - 2, my + 6, 2),
                           (mx + 7, my - 4, 2)):
        d.ellipse([ccx - cr, ccy - cr, ccx + cr, ccy + cr], fill=(145, 135, 125))
        d.arc([ccx - cr, ccy - cr, ccx + cr, ccy + cr], 180, 300,
              fill=(210, 200, 190), width=1)
    d.ellipse([mx - mr + 3, my - mr + 3, mx - mr + 8, my - mr + 7],
              fill=(205, 195, 185))
    # orbit ellipse with a faint halo, then the bright line
    d.ellipse([x + 8, y + h // 2 - 6, x + w - 8, y + h - 4],
              outline=(50, 110, 120), width=3)
    d.ellipse([x + 8, y + h // 2 - 6, x + w - 8, y + h - 4], outline=TEAL,
              width=1)
    # spacecraft: solar panels with a cell grid, a gold-foil bus with
    # facets and a dish, and a layered thruster plume
    px, py = cx - w // 4, cy + h // 6
    for sgn in (-1, 1):
        px0 = px - 14 if sgn < 0 else px + 4
        d.rectangle([px0, py - 3, px0 + 10, py + 3], fill=(50, 80, 150),
                    outline=(30, 50, 100), width=1)
        d.rectangle([px0, py - 3, px0 + 10, py - 1], fill=(90, 130, 200))
        for gx2 in range(px0 + 3, px0 + 10, 3):
            d.line([gx2, py - 3, gx2, py + 3], fill=(120, 160, 220), width=1)
        d.line([px0, py, px0 + 10, py], fill=(120, 160, 220), width=1)
    d.rectangle([px - 4, py - 6, px + 4, py + 6], fill=(210, 175, 70),
                outline=(150, 120, 40), width=1)
    d.line([px - 4, py - 2, px + 4, py - 2], fill=(160, 125, 45), width=1)
    d.line([px - 4, py + 2, px + 4, py + 2], fill=(240, 205, 100), width=1)
    d.ellipse([px - 2, py - 2, px + 2, py + 2], fill=GOLD)
    d.ellipse([px - 3, py - 8, px + 1, py - 4], fill=(240, 240, 240),
              outline=(180, 180, 180), width=1)
    d.polygon([(px - 5, py + 6), (px + 5, py + 6), (px, py + 18)],
              fill=(255, 140, 30))
    d.polygon([(px - 3, py + 6), (px + 3, py + 6), (px, py + 14)],
              fill=(255, 190, 70))
    d.polygon([(px - 1, py + 6), (px + 1, py + 6), (px, py + 11)],
              fill=(255, 235, 150))


def illus_bridge(d, x, y, w, h, big):
    cx, cy = x + w // 2, y + h // 2
    # sky gradient with soft shaded clouds
    vgrad(d, x, y, w, h // 2, (195, 222, 240), (235, 228, 205))
    for (ccx, ccy, cr) in ((cx + 34, y + 7, 7), (x + w - 34, y + 5, 6)):
        d.ellipse([ccx - cr, ccy - cr // 2, ccx + cr, ccy + cr // 2],
                  fill=(255, 255, 255))
        d.ellipse([ccx - cr, ccy, ccx + cr, ccy + cr // 2],
                  fill=(215, 228, 238))
    # sea gradient with wave highlights and the bridge's reflection
    vgrad(d, x, y + h // 2, w, h - h // 2, (115, 168, 208), (70, 130, 182))
    for wy in range(y + h // 2 + 4, y + h - 2, 7):
        d.arc([x + 4, wy - 4, x + w - 4, wy + 4], 0, 180, fill=(90, 140, 190),
              width=1)
        d.arc([x + 8, wy - 5, x + w - 8, wy + 3], 0, 180,
              fill=(200, 225, 240), width=1)
    for (rx2, ry2, rw2) in ((cx - 30, y + h - 12, 14), (cx + 16, y + h - 8, 12)):
        d.ellipse([rx2, ry2, rx2 + rw2, ry2 + 4], fill=(60, 110, 160))
    # bridge deck with railings, a lit top edge, support pillars and
    # their reflections in the water
    deck = y + h // 2 - 8
    d.line([x + 4, deck, x + w - 4, deck], fill=INK, width=3)
    d.line([x + 4, deck - 2, x + w - 4, deck - 2], fill=(200, 200, 205),
           width=1)
    for px2 in range(x + 8, x + w - 8, 12):
        d.line([px2, deck - 5, px2, deck], fill=(90, 90, 95), width=1)
    d.line([x + 8, deck - 5, x + w - 8, deck - 5], fill=(120, 120, 125),
           width=1)
    for px2 in (x + w // 4, x + 3 * w // 4):
        d.rectangle([px2 - 2, deck, px2 + 2, y + h - 6], fill=(80, 80, 88))
        d.rectangle([px2 - 2, deck + 6, px2 + 2, y + h - 6],
                    fill=(60, 110, 160))
    # broken span: jagged broken edges and bent rebar
    gap = (cx - 12, cx + 12)
    d.line([gap[0], deck, gap[0], deck + 10], fill=INK, width=2)
    d.line([gap[1], deck, gap[1], deck + 10], fill=INK, width=2)
    d.polygon([(gap[0], deck), (gap[0] + 5, deck + 12), (gap[0] + 10, deck)],
              fill=(150, 140, 120))
    d.polygon([(gap[1], deck), (gap[1] - 5, deck + 12), (gap[1] - 10, deck)],
              fill=(130, 120, 105))
    d.line([gap[0] + 2, deck + 2, gap[0] + 6, deck + 9], fill=(70, 65, 60),
           width=1)
    d.line([gap[1] - 2, deck + 2, gap[1] - 6, deck + 9], fill=(70, 65, 60),
           width=1)
    # steel arch with a highlight edge and suspension cables to the deck
    ar = 34 if big else 16
    d.arc([cx - ar, deck - 26, cx + ar, deck + 8], 180, 360, fill=(70, 75, 85),
          width=4)
    d.arc([cx - ar + 1, deck - 27, cx + ar - 1, deck + 7], 180, 360,
          fill=(150, 160, 175), width=1)
    d.arc([cx - ar, deck - 26, cx + ar, deck + 8], 200, 340, fill=RED, width=1)
    for kx in range(cx - ar + 6, cx + ar - 4, 10):
        d.line([kx, deck - 9 - int(17 * (1 - ((kx - cx) / ar) ** 2) ** 0.5),
                kx, deck], fill=(100, 105, 115), width=1)
    # fallen span in the water with a splash ring and droplets
    d.polygon([(gap[0] + 2, deck + 14), (gap[1] - 2, deck + 14),
               (gap[1] - 6, deck + 22), (gap[0] + 6, deck + 22)], fill=(120, 110, 100))
    d.polygon([(gap[0] + 2, deck + 14), (gap[1] - 2, deck + 14),
               (gap[1] - 4, deck + 17), (gap[0] + 4, deck + 17)],
              fill=(145, 135, 120))
    d.arc([gap[0] - 2, deck + 18, gap[1] + 2, deck + 26], 0, 180,
          fill=(220, 235, 245), width=1)
    for (sx2, sy2) in ((gap[0] - 4, deck + 16), (gap[1] + 4, deck + 17),
                       (cx, deck + 12)):
        d.ellipse([sx2 - 1, sy2 - 1, sx2 + 1, sy2 + 1], fill=(230, 240, 248))
    # flags
    d.rectangle([x + 6, y + 6, x + 22, y + 16], fill=BLUE)
    d.rectangle([x + 6, y + 16, x + 22, y + 26], fill=GOLD)


def illus_drone(d, x, y, w, h, big):
    cx, cy = x + w // 2, y + h // 2
    # dusk sky: warm orange fading to dusty rose at the horizon
    vgrad(d, x, y, w, h * 2 // 3, (250, 190, 120), (205, 110, 125))
    # low sun with a layered glow
    for rr, col in ((18, (255, 205, 130)), (13, (255, 220, 150))):
        d.ellipse([x + w - 26 - rr, y + 14 - rr, x + w - 26 + rr,
                   y + 14 + rr], fill=col)
    d.ellipse([x + w - 26, y + 6, x + w - 10, y + 22], fill=(255, 220, 120))
    d.ellipse([x + w - 24, y + 8, x + w - 16, y + 16], fill=(255, 240, 180))
    # sea: shaded blue with wave highlights and a sun-glitter column
    vgrad(d, x, y + h * 2 // 3, w, h - h * 2 // 3, (95, 145, 190),
          (55, 105, 155))
    for wy in range(y + h * 2 // 3 + 3, y + h - 2, 6):
        d.line([x + 4, wy, x + w - 4, wy], fill=(140, 190, 220), width=1)
        d.line([x + 10, wy + 2, x + w - 10, wy + 2], fill=(180, 210, 235),
               width=1)
    for gy2 in range(y + h * 2 // 3 + 4, y + h - 4, 5):
        d.line([x + w - 34, gy2, x + w - 16, gy2], fill=(255, 200, 120),
               width=1)
    # tanker: shaded red hull with a waterline, deck containers and a
    # white bridge tower with lit windows, plus its reflection
    d.rectangle([x + 8, y + h - 20, x + w - 8, y + h - 12], fill=(120, 40, 40))
    d.rectangle([x + 8, y + h - 20, x + w - 8, y + h - 18], fill=(165, 60, 55))
    d.line([x + 8, y + h - 13, x + w - 8, y + h - 13], fill=(30, 30, 35),
           width=1)
    for i, ccol in enumerate(((70, 110, 160), (90, 140, 90),
                             (170, 100, 60), (120, 120, 125))):
        cxx = x + 14 + i * 22
        d.rectangle([cxx, y + h - 30, cxx + 18, y + h - 20], fill=ccol,
                    outline=(60, 55, 50), width=1)
        d.rectangle([cxx, y + h - 30, cxx + 18, y + h - 28], fill=ccol)
        d.line([cxx, y + h - 26, cxx + 18, y + h - 26], fill=(60, 55, 50),
               width=1)
    d.rectangle([x + w - 26, y + h - 30, x + w - 12, y + h - 20],
                fill=(240, 240, 240))
    d.rectangle([x + w - 26, y + h - 30, x + w - 12, y + h - 27],
                fill=(255, 255, 255))
    for wy in (y + h - 26, y + h - 23):
        d.rectangle([x + w - 24, wy, x + w - 14, wy + 2], fill=(40, 60, 90))
    d.line([x + w - 19, y + h - 36, x + w - 19, y + h - 30], fill=(80, 80, 80),
           width=1)
    d.ellipse([x + 8, y + h - 12, x + w - 8, y + h - 9], fill=(90, 35, 35))
    d.arc([x + 6, y + h - 14, x + 22, y + h - 8], 180, 360,
          fill=(220, 230, 240), width=1)
    # MQ-9 drone: shaded fuselage with a sensor ball, long wings with
    # navigation lights, V-tail, a blurred rear propeller and a soft
    # shadow on the open water below the tanker
    dx, dy = cx, y + h // 3
    d.ellipse([dx - 14, y + h - 10, dx + 14, y + h - 6], fill=(45, 85, 130))
    # wings: light top surface, dark underside edge
    d.polygon([(dx - 6, dy - 2), (dx - 46, dy - 7), (dx - 46, dy - 3),
               (dx - 6, dy + 3)], fill=(110, 110, 115))
    d.polygon([(dx + 6, dy - 2), (dx + 46, dy - 7), (dx + 46, dy - 3),
               (dx + 6, dy + 3)], fill=(110, 110, 115))
    d.line([dx - 46, dy - 3, dx - 6, dy + 3], fill=(70, 70, 75), width=1)
    d.line([dx + 6, dy + 3, dx + 46, dy - 3], fill=(70, 70, 75), width=1)
    d.ellipse([dx - 48, dy - 8, dx - 45, dy - 5], fill=(255, 80, 80))
    d.ellipse([dx + 45, dy - 8, dx + 48, dy - 5], fill=(80, 220, 120))
    # fuselage with a rounded nose and a belly sensor ball
    d.ellipse([dx - 12, dy - 3, dx + 12, dy + 3], fill=(60, 60, 60))
    d.ellipse([dx - 12, dy - 3, dx + 12, dy], fill=(85, 85, 90))
    d.ellipse([dx + 4, dy + 2, dx + 10, dy + 8], fill=(90, 90, 95))
    d.ellipse([dx + 5, dy + 3, dx + 8, dy + 6], fill=(180, 180, 185))
    d.rectangle([dx - 2, dy - 8, dx + 2, dy + 2], fill=(60, 60, 60))
    d.line([dx - 8, dy - 1, dx + 8, dy - 1], fill=(40, 40, 40), width=1)
    # V-tail fins and the blurred rear propeller disc
    d.polygon([(dx - 10, dy), (dx - 18, dy - 8), (dx - 14, dy - 8),
               (dx - 8, dy - 2)], fill=(70, 70, 75))
    d.polygon([(dx + 10, dy), (dx + 18, dy - 8), (dx + 14, dy - 8),
               (dx + 8, dy - 2)], fill=(70, 70, 75))
    d.ellipse([dx - 14, dy - 6, dx - 12, dy + 6], fill=(150, 150, 155))
    d.ellipse([dx - 13, dy - 4, dx - 13, dy + 4], fill=(200, 200, 205))
    # radar arcs from the ship's bridge
    for r in (8, 14, 20, 26):
        d.arc([x + w - 30 - r, y + h - 30 - r, x + w - 30 + r, y + h - 30 + r],
              270, 360, fill=(255, 255, 255), width=1)


def illus_datacentre(d, x, y, w, h, big):
    cx, cy = x + w // 2, y + h // 2
    # cool server-room wall and a floor strip with rack reflections
    vgrad(d, x, y, w, h, (238, 240, 247), (222, 226, 235))
    d.rectangle([x, y + h - 10, x + w, y + h], fill=(200, 205, 215))
    # server racks with depth: lit top edge, shadowed right side, vent
    # slots, varied status LEDs, an LCD on one unit, cable bundles and
    # castor wheels
    for i in range(3):
        rx = x + 6 + i * (w - 12) // 3
        rw = (w - 12) // 3 - 4
        d.rectangle([rx, y + h - 12, rx + rw, y + h - 10], fill=(140, 145, 160))
        d.rectangle([rx, y + 8, rx + rw, y + h - 16], fill=(50, 55, 70),
                    outline=INK, width=1)
        d.rectangle([rx, y + 8, rx + rw, y + 10], fill=(90, 95, 110))
        d.rectangle([rx + rw - 3, y + 8, rx + rw, y + h - 16],
                    fill=(30, 35, 45))
        for j, ry in enumerate(range(y + 12, y + h - 20, 9)):
            vgrad(d, rx + 3, ry, rw - 6, 5, (100, 130, 190), (75, 105, 165))
            d.line([rx + 4, ry + 1, rx + rw - 10, ry + 1], fill=(60, 85, 140),
                   width=1)
            d.line([rx + 4, ry + 3, rx + rw - 10, ry + 3], fill=(60, 85, 140),
                   width=1)
            led = [(120, 220, 120), (120, 220, 120), (255, 190, 60),
                   (120, 220, 120), (255, 90, 70)][(i * 3 + j) % 5]
            d.ellipse([rx + rw - 6, ry + 1, rx + rw - 3, ry + 4], fill=led)
            if i == 1 and j == 1:
                d.rectangle([rx + 5, ry + 1, rx + 18, ry + 4],
                            fill=(180, 220, 240))
                d.line([rx + 6, ry + 2, rx + 16, ry + 2], fill=(40, 80, 120),
                       width=1)
        # cable bundle drooping from the rack to the floor
        ccol = [(60, 110, 200), (220, 170, 60), (200, 80, 70)][i]
        d.arc([rx + 4, y + h - 22, rx + rw - 4, y + h - 8], 0, 180,
              fill=ccol, width=2)
        d.ellipse([rx + 3, y + h - 13, rx + 6, y + h - 10], fill=(35, 40, 50))
        d.ellipse([rx + rw - 6, y + h - 13, rx + rw - 3, y + h - 10],
                  fill=(35, 40, 50))
    # tax document with a folded corner, text lines and a cast shadow,
    # and a glowing lightning bolt
    dx = cx + w // 4
    d.rectangle([dx - 10, y + h - 24, dx + 14, y + h - 6],
                fill=(210, 212, 218))
    d.rectangle([dx - 12, y + h - 26, dx + 12, y + h - 8], fill=(255, 255, 255),
                outline=INK, width=1)
    d.polygon([(dx + 12, y + h - 26), (dx + 12, y + h - 18),
               (dx + 4, y + h - 26)], fill=(225, 228, 235))
    d.text((dx + 1, y + h - 25), "$", font=SANS_B(13), fill=(180, 30, 30),
           anchor="ma")
    d.text((dx, y + h - 24), "$", font=SANS_B(13), fill=RED, anchor="ma")
    # lightning bolt with a pale glow behind it
    bx0 = cx - w // 4
    d.polygon([(bx0, y + 4), (bx0 - 8, y + 18), (bx0 - 2, y + 18),
               (bx0 - 8, y + 32), (bx0 + 6, y + 15), (bx0 - 1, y + 15)],
              fill=(255, 230, 150))
    d.polygon([(bx0, y + 6), (bx0 - 6, y + 18), (bx0 - 1, y + 18),
               (bx0 - 6, y + 30), (bx0 + 4, y + 16), (bx0 - 1, y + 16)],
              fill=(255, 200, 40), outline=GOLD, width=1)


def illus_flags(d, x, y, w, h, big):
    """China (left) and Japan (right) flags, large and bold: one big yellow
    five-pointed star + four small stars on a red field, and a big red disc
    on a white field. No thin lines between the flags — a clean gap."""
    # China flag: left half, red field filling most of it.
    fx0, fy0 = x + 2, y + 4
    fw, fh = w // 2 - 6, h - 8
    d.rectangle([fx0, fy0, fx0 + fw, fy0 + fh], fill=RED)
    # Big star, clear of the "NN · RR" header chip at the top-left.
    d.polygon(star_points(fx0 + 30, fy0 + 26, 10), fill=(255, 220, 60))
    # Four small stars arcing to the upper right of the big star.
    for (sx, sy) in ((fx0 + 54, fy0 + 12), (fx0 + 62, fy0 + 22),
                      (fx0 + 58, fy0 + 32), (fx0 + 48, fy0 + 38)):
        d.polygon(star_points(sx, sy, 4), fill=(255, 220, 60))
    # Japan flag: right half, white field with a strong outline, big disc.
    jx0 = x + w // 2 + 4
    jw = x + w - 2 - jx0
    d.rectangle([jx0, fy0, jx0 + jw, fy0 + fh], fill=(255, 255, 255),
                outline=INK, width=2)
    d.ellipse([jx0 + jw // 2 - 16, y + h // 2 - 16,
               jx0 + jw // 2 + 16, y + h // 2 + 16], fill=RED)


def illus_makefun(d, x, y, w, h, big):
    """Make.fun ghost mascot, drawn WHOLE with margins on every side:
    dome head, body, wavy bottom edge, eyes and smile all inside the
    band. Confetti goes behind the ghost so nothing speckles its face;
    the gold coin stays top-right."""
    cx, cy = x + w // 2, y + h // 2
    d.rectangle([x, y, x + w, y + h], fill=(238, 230, 250))
    # confetti first (behind the ghost)
    rng = random.Random(31)
    for _ in range(14 if big else 7):
        px = x + rng.randint(2, w - 4)
        py = y + rng.randint(2, h - 4)
        d.rectangle([px, py, px + 3, py + 2],
                    fill=rng.choice([RED, GOLD, TEAL, PURPLE]))
    # ghost: sized to the band height with a margin all round
    gh = h - 10
    gw = int(gh * 0.92)
    gx0, gy0 = cx - gw // 2, y + 5
    gy1 = gy0 + gh
    # dome head + straight body
    d.ellipse([gx0, gy0, gx0 + gw, gy0 + gw // 2 + 8], fill=PURPLE)
    d.rectangle([gx0, gy0 + gw // 4, gx0 + gw, gy1 - 7], fill=PURPLE)
    # wavy bottom edge: four points, all inside the band
    step = gw // 4
    pts = [(gx0, gy1 - 7), (gx0 + gw, gy1 - 7)]
    for i in range(4):
        pts.append((gx0 + gw - i * step - step // 2, gy1))
        pts.append((gx0 + gw - (i + 1) * step, gy1 - 7))
    d.polygon(pts, fill=PURPLE)
    # eyes with glints, and a smile — all well inside the head
    ex, ey = gw // 5, gy0 + gw // 4 - 2
    ew, eh = max(6, gw // 7), max(8, gw // 5)
    d.ellipse([cx - ex - ew // 2, ey, cx - ex + ew // 2, ey + eh], fill=INK)
    d.ellipse([cx + ex - ew // 2, ey, cx + ex + ew // 2, ey + eh], fill=INK)
    d.ellipse([cx - ex - ew // 2 + 1, ey + 1, cx - ex + 1, ey + 4],
              fill=(255, 255, 255))
    d.ellipse([cx + ex - ew // 2 + 1, ey + 1, cx + ex + 1, ey + 4],
              fill=(255, 255, 255))
    d.arc([cx - gw // 6, ey + eh + 2, cx + gw // 6, ey + eh + 12], 0, 180,
          fill=INK, width=3)
    # gold coin, top-right, clear of the ghost
    d.ellipse([x + w - 30, y + 8, x + w - 12, y + 26], fill=(255, 210, 80),
              outline=GOLD, width=2)
    d.text((x + w - 21, y + 11), "$", font=SANS_B(11), fill=GOLD, anchor="ma")


def illus_denmark(d, x, y, w, h, big):
    cx, cy = x + w // 2, y + h // 2
    d.rectangle([x, y, x + w, y + h], fill=(240, 235, 220))
    # Danish flag (Dannebrog): red field with a white cross whose
    # vertical bar sits toward the hoist (left). Bold arms and true
    # proportions, so it reads as Denmark, not as stripes. The design
    # is UNCHANGED — realism comes only from shading: a soft vertical
    # gradient and fold shadows on the red field, a bevelled white
    # cross, and a drop shadow under the whole flag.
    fx, fy = x + 6, y + 6
    fw, fh = 90, 48
    d.rectangle([fx + 2, fy + 2, fx + fw + 2, fy + fh + 2],
                fill=(215, 210, 195))
    for yy in range(fh):
        t = yy / max(1, fh - 1)
        d.line([fx, fy + yy, fx + fw, fy + yy],
               fill=(int(192 - 32 * t), int(45 - 25 * t), int(45 - 25 * t)))
    for (ax0, ax1) in ((10, 16), (60, 66)):
        d.polygon([(fx + ax0, fy), (fx + ax1, fy), (fx + ax1 + 14, fy + fh),
                   (fx + ax0 + 14, fy + fh)], fill=(150, 18, 18))
    d.rectangle([fx + 26, fy, fx + 37, fy + fh], fill=(255, 255, 255))
    d.rectangle([fx, fy + fh // 2 - 5, fx + fw, fy + fh // 2 + 6],
                fill=(255, 255, 255))
    d.line([fx + 26, fy + fh, fx + 37, fy + fh], fill=(225, 225, 225),
           width=1)
    d.line([fx, fy + fh // 2 + 6, fx + fw, fy + fh // 2 + 6],
           fill=(225, 225, 225), width=1)
    d.rectangle([fx, fy, fx + fw, fy + fh], outline=INK, width=1)
    # shield with a drop shadow, a lit top and a highlight
    sh = 18 if big else 11
    sx, sy = cx + w // 5, cy + 2
    shpts = [(sx, sy - sh), (sx + sh, sy - sh + 6), (sx + sh, sy + 4),
             (sx, sy + sh + 6), (sx - sh, sy + 4), (sx - sh, sy - sh + 6)]
    d.polygon([(px2 + 2, py2 + 2) for (px2, py2) in shpts],
              fill=(210, 200, 190))
    d.polygon(shpts, fill=(250, 225, 220), outline=RED, width=3)
    d.ellipse([sx - sh + 3, sy - sh + 3, sx - sh + 10, sy - sh + 9],
              fill=(255, 245, 240))
    d.text((sx + 1, sy - 5), "!", font=SANS_B(14 if big else 10),
           fill=(160, 20, 20), anchor="ma")
    d.text((sx, sy - 6), "!", font=SANS_B(14 if big else 10), fill=RED,
           anchor="ma")
    # scales of justice: shaded gold pans, a highlighted post, and a
    # soft shadow on the ground beneath
    bx = x + w - 26
    d.ellipse([bx - 12, y + h - 8, bx + 12, y + h - 5], fill=(215, 210, 195))
    d.line([bx, y + h - 24, bx, y + h - 8], fill=INK, width=2)
    d.line([bx - 1, y + h - 24, bx - 1, y + h - 8], fill=(150, 150, 150),
           width=1)
    d.line([bx - 10, y + h - 24, bx + 10, y + h - 24], fill=INK, width=2)
    d.line([bx - 10, y + h - 25, bx + 10, y + h - 25], fill=(200, 170, 90),
           width=1)
    d.polygon([(bx - 12, y + h - 22), (bx - 6, y + h - 22), (bx - 9, y + h - 14)],
              fill=GOLD)
    d.polygon([(bx - 12, y + h - 22), (bx - 6, y + h - 22), (bx - 9, y + h - 18)],
              fill=(255, 215, 100))
    d.polygon([(bx + 6, y + h - 22), (bx + 12, y + h - 22), (bx + 9, y + h - 14)],
              fill=GOLD)
    d.polygon([(bx + 6, y + h - 22), (bx + 12, y + h - 22), (bx + 9, y + h - 18)],
              fill=(255, 215, 100))


def illus_houthi(d, x, y, w, h, big):
    """Red Sea port under threat: container cranes and a cargo ship at
    dusk, with a missile streaking in from the upper right."""
    cx, cy = x + w // 2, y + h // 2
    # dusk sky with a low sun and soft clouds
    vgrad(d, x, y, w, h * 2 // 3, (250, 190, 120), (215, 125, 135))
    for rr, col in ((14, (255, 210, 140)), (10, (255, 225, 160))):
        d.ellipse([x + w - 30 - rr, y + 14 - rr, x + w - 30 + rr,
                   y + 14 + rr], fill=col)
    d.ellipse([x + w - 30, y + 7, x + w - 16, y + 21], fill=(255, 235, 180))
    for (ccx, ccy, cr) in ((x + 40, y + 8, 7), (x + 110, y + 6, 6)):
        d.ellipse([ccx - cr, ccy - cr // 2, ccx + cr, ccy + cr // 2],
                  fill=(255, 240, 230))
        d.ellipse([ccx - cr, ccy, ccx + cr, ccy + cr // 2],
                  fill=(225, 200, 195))
    # sea with wave highlights
    vgrad(d, x, y + h * 2 // 3, w, h - h * 2 // 3, (95, 145, 190),
          (60, 110, 160))
    for wy in range(y + h * 2 // 3 + 4, y + h - 2, 7):
        d.arc([x + 4, wy - 4, x + w - 4, wy + 4], 0, 180,
              fill=(150, 195, 225), width=1)
    # port dock with stacked containers and two gantry cranes
    d.rectangle([x, y + h - 12, x + 70, y + h], fill=(90, 90, 95))
    for i, ccol in enumerate(((70, 110, 160), (170, 100, 60), (90, 140, 90))):
        cxx = x + 8 + i * 18
        d.rectangle([cxx, y + h - 22, cxx + 16, y + h - 12], fill=ccol,
                    outline=(60, 55, 50), width=1)
        d.line([cxx, y + h - 17, cxx + 16, y + h - 17], fill=(60, 55, 50),
               width=1)
    for (kx, kh) in ((18, 34), (52, 28)):
        d.rectangle([x + kx, y + h - 12 - kh, x + kx + 4, y + h - 12],
                    fill=(60, 60, 68))
        d.rectangle([x + kx, y + h - 12 - kh, x + kx + 1, y + h - 12],
                    fill=(110, 110, 118))
        d.rectangle([x + kx, y + h - 12 - kh, x + kx + 34, y + h - 9 - kh],
                    fill=(70, 70, 78))
        d.line([x + kx + 30, y + h - 9 - kh, x + kx + 30, y + h - 22],
               fill=(90, 90, 98), width=1)
        d.rectangle([x + kx + 26, y + h - 22, x + kx + 34, y + h - 16],
                    fill=(120, 120, 130), outline=(70, 70, 78), width=1)
    d.ellipse([x + 20, y + h - 12 - 34 - 3, x + 24, y + h - 12 - 34 + 1],
              fill=(255, 80, 80))
    # cargo ship with containers, a white bridge and a reflection
    d.rectangle([x + 95, y + h - 18, x + w - 8, y + h - 8], fill=(120, 40, 40))
    d.rectangle([x + 95, y + h - 18, x + w - 8, y + h - 16], fill=(165, 60, 55))
    d.line([x + 95, y + h - 9, x + w - 8, y + h - 9], fill=(30, 30, 35),
           width=1)
    for i, ccol in enumerate(((70, 110, 160), (90, 140, 90),
                             (170, 100, 60), (120, 120, 125))):
        cxx = x + 100 + i * 18
        d.rectangle([cxx, y + h - 28, cxx + 16, y + h - 18], fill=ccol,
                    outline=(60, 55, 50), width=1)
    d.rectangle([x + w - 26, y + h - 32, x + w - 12, y + h - 18],
                fill=(240, 240, 240))
    for wy in (y + h - 29, y + h - 25):
        d.rectangle([x + w - 24, wy, x + w - 14, wy + 2], fill=(40, 60, 90))
    d.ellipse([x + 95, y + h - 8, x + w - 8, y + h - 5], fill=(90, 35, 35))
    d.arc([x + 90, y + h - 12, x + 104, y + h - 6], 180, 360,
          fill=(220, 230, 240), width=1)
    # missile streaking in from the upper right, with a layered trail
    d.line([x + 150, y + 6, x + 122, y + 26], fill=(255, 140, 40), width=4)
    d.line([x + 150, y + 6, x + 122, y + 26], fill=(255, 200, 90), width=2)
    d.line([x + 150, y + 6, x + 122, y + 26], fill=(255, 250, 200), width=1)
    d.polygon([(x + 122, y + 26), (x + 128, y + 22), (x + 118, y + 20)],
              fill=(220, 220, 225))
    d.polygon([(x + 122, y + 26), (x + 125, y + 23), (x + 120, y + 22)],
              fill=RED)
    d.ellipse([x + 119, y + 23, x + 125, y + 29], fill=(255, 220, 130))
    d.ellipse([x + 121, y + 25, x + 123, y + 27], fill=(255, 250, 210))


def illus_uranium(d, x, y, w, h, big):
    """Uranium enrichment hall: two rows of centrifuges receding into
    the hall, with pipes, gauges and a radiation warning sign."""
    cx, cy = x + w // 2, y + h // 2
    # hall: pale gradient, a warm ceiling light, a floor with reflections
    vgrad(d, x, y, w, h, (235, 235, 240), (210, 215, 225))
    d.ellipse([cx - 30, y - 8, cx + 30, y + 8], fill=(250, 240, 210))
    d.ellipse([cx - 16, y - 4, cx + 16, y + 4], fill=(255, 248, 225))
    d.rectangle([x, y + h - 10, x + w, y + h], fill=(190, 195, 205))
    d.line([x, y + h - 10, x + w, y + h - 10], fill=(170, 175, 188), width=1)
    # back row of centrifuges, smaller and paler for depth
    for i in range(5):
        px = x + 14 + i * 32
        d.rectangle([px, y + 20, px + 10, y + 42], fill=(150, 155, 165),
                    outline=(110, 115, 125), width=1)
        d.ellipse([px, y + 16, px + 10, y + 22], fill=(170, 175, 185))
        d.rectangle([px, y + 42, px + 10, y + 45], fill=(120, 125, 135))
    d.line([x + 14, y + 24, x + 14 + 4 * 32 + 10, y + 24],
           fill=(110, 115, 125), width=1)
    # front row: tall metallic cylinders with a lit edge, a shadow
    # edge, top caps and connecting pipes
    for i in range(4):
        px = x + 10 + i * 44
        d.rectangle([px, y + 28, px + 14, y + h - 10], fill=(175, 180, 190),
                    outline=(120, 125, 135), width=1)
        d.rectangle([px, y + 28, px + 3, y + h - 10], fill=(215, 220, 230))
        d.rectangle([px + 11, y + 28, px + 14, y + h - 10],
                    fill=(130, 135, 145))
        d.ellipse([px, y + 24, px + 14, y + 30], fill=(200, 205, 215))
        d.ellipse([px + 2, y + 25, px + 6, y + 28], fill=(235, 240, 248))
        d.rectangle([px, y + h - 10, px + 14, y + h - 7],
                    fill=(140, 145, 155))
        d.ellipse([px + 2, y + h - 7, px + 12, y + h - 4],
                  fill=(165, 170, 182))
    d.line([x + 10, y + 32, x + 10 + 3 * 44 + 14, y + 32],
           fill=(120, 125, 135), width=2)
    d.line([x + 10, y + 32, x + 10 + 3 * 44 + 14, y + 32],
           fill=(200, 205, 215), width=1)
    for px in (x + 32, x + 76, x + 120):
        d.line([px, y + 32, px, y + 42], fill=(120, 125, 135), width=1)
    # wall gauges and a radiation trefoil sign
    for (gx2, gy2) in ((x + w - 24, y + 10), (x + w - 40, y + 10)):
        d.ellipse([gx2 - 5, gy2 - 5, gx2 + 5, gy2 + 5], fill=(250, 250, 245),
                  outline=INK, width=1)
        d.line([gx2, gy2, gx2 + 3, gy2 - 3], fill=RED, width=1)
    tx0, ty0 = x + w - 52, y + 24
    d.polygon([(tx0, ty0 + 12), (tx0 + 12, ty0 + 12), (tx0 + 6, ty0)],
              fill=(255, 200, 40), outline=INK, width=1)
    d.ellipse([tx0 + 5, ty0 + 7, tx0 + 7, ty0 + 9], fill=INK)
    for (dx2, dy2) in ((tx0 + 3, ty0 + 9), (tx0 + 7, ty0 + 9),
                       (tx0 + 5, ty0 + 5)):
        d.ellipse([dx2 - 1, dy2 - 1, dx2 + 1, dy2 + 1], fill=INK)


ILLUS = {1: illus_cop31, 2: illus_missiles, 3: illus_quake, 4: illus_davao,
         5: illus_bitcoin, 6: illus_rahul, 7: illus_bepi, 8: illus_bridge,
         9: illus_drone, 10: illus_datacentre, 11: illus_flags,
         12: illus_makefun, 13: illus_denmark, 14: illus_houthi,
         15: illus_uranium}

# ---------------------------------------------------------------- page

def draw_illus_layer(img, num, x, y, w, h, big):
    """Draw one illustration onto its own layer and paste it, so no stroke
    can spill past the illustration box onto neighbouring text."""
    layer = Image.new("RGB", (w, h), CARD)
    ld = ImageDraw.Draw(layer)
    ILLUS[num](ld, 0, 0, w, h, big)
    img.paste(layer, (x, y))

def draw_paper(d):
    """Subtle vertical gradient + deterministic speckle, for a printed feel
    and a denser PNG."""
    for yy in range(H):
        t = yy / H
        c = (247 - int(6 * t), 241 - int(7 * t), 222 - int(9 * t))
        d.line([0, yy, W, yy], fill=c)
    rng = random.Random(20261121)
    for _ in range(90000):
        px = rng.randint(0, W - 1)
        py = rng.randint(0, H - 1)
        shade = rng.choice([(238, 230, 205), (250, 246, 232), (235, 226, 198),
                            (252, 248, 236)])
        d.point((px, py), fill=shade)
    # faint diagonal hatch, like newsprint grain
    for xx in range(-H, W, 7):
        d.line([xx, 0, xx + H, H], fill=(244, 237, 216), width=1)
    # faint column rules, like newsprint
    for xx in range(0, W, 7):
        if xx % 49 == 0:
            d.line([xx, 0, xx, H], fill=(243, 236, 214), width=1)


def main():
    img = Image.new("RGB", (W, H), CREAM)
    d = ImageDraw.Draw(img)
    draw_paper(d)
    M = 16

    # --- top strip ---
    d.rectangle([0, 0, W, 22], fill=INK)
    d.text((M, 3), "THE WORLD IN ONE DAY", font=SANS_B(13),
           fill=(255, 255, 255))
    d.text((W - M, 3), "35 STORIES  ·  7 REGIONS  ·  EVERY ONE DATED",
           font=SANS_B(12), fill=(255, 220, 120), anchor="ra")

    # --- masthead: the date is the giant headline (judge criterion 1),
    # the entry name stays as the smaller red caps line below it ---
    d.text((W // 2, 28), "Saturday 21 November 2026", font=SERIF_B(56),
           fill=INK, anchor="ma")
    d.line([M, 90, W - M, 90], fill=INK, width=2)
    d.text((W // 2, 96), "THE TWENTY-FIRST", font=SANS_B(22),
           fill=RED, anchor="ma")
    d.text((W // 2, 122),
           "COP31 in overtime  •  Three missiles down over Riyadh  •  "
           "Peru shaken by a 6.7 quake",
           font=SERIF(15), fill=INK, anchor="ma")

    # --- region strip: equal cells, counts sum to 35 ---
    # (Proportional widths made the AFRICA cell unreadable, so the strip
    # uses equal cells and the counts carry the breakdown.)
    counts = {}
    for _, r, *_ in HEROES + FEATURES + FEATURES3:
        counts[r] = counts.get(r, 0) + 1
    for _, r, *_ in BRIEFS:
        counts[r] = counts.get(r, 0) + 1
    assert sum(counts.values()) == 35, counts
    y = 142
    x = M
    total_w = W - 2 * M
    cw_strip = total_w // 7
    for i, (name, code, col) in enumerate(REGIONS):
        n = counts[code]
        seg = cw_strip if i < 6 else total_w - 6 * cw_strip
        d.rectangle([x, y, x + seg - 2, y + 18], fill=col)
        d.text((x + seg // 2 - 1, y + 3), f"{name} {n}", font=SANS_B(11),
               fill=(255, 255, 255), anchor="ma")
        x += seg

    # --- stat strip: 6 numbers ---
    y = 166
    bw = (W - 2 * M) // 6
    for i, (num, lab) in enumerate(STATS):
        bx = M + i * bw
        d.rectangle([bx + 2, y, bx + bw - 2, y + 34], outline=LINE, width=1,
                    fill=PAPER2)
        d.text((bx + bw // 2, y + 2), num, font=SANS_B(15), fill=RED,
               anchor="ma")
        d.text((bx + bw // 2, y + 19), lab, font=SANS(10), fill=INK,
               anchor="ma")

    # --- 3 heroes ---
    y0 = 206
    cw = (W - 2 * M - 2 * 10) // 3
    for i, (num, reg, banner, head, summ, src, lab) in enumerate(HEROES):
        x = M + i * (cw + 10)
        col = REG_COL[reg]
        d.rectangle([x, y0, x + cw, y0 + 152], outline=LINE, width=1,
                    fill=CARD)
        # header bar 16 px (was 20): the freed 4 px pay for the banner
        d.rectangle([x, y0, x + cw, y0 + 16], fill=col)
        d.text((x + 6, y0 + 1), f"{num:02d}", font=SANS_B(13),
               fill=(255, 255, 255))
        d.text((x + cw - 6, y0 + 2), REG_NAME[reg], font=SANS_B(11),
               fill=(255, 255, 255), anchor="ra")
        # illustration band stays 38 px: the scenes are composed for it
        # (the COP31 globe needs r >= 9) and still render fully
        draw_illus_layer(img, num, x + 4, y0 + 20, cw - 8, 38, big=True)
        # caps banner bar, like the top 3: red bar, white bold caps
        d.rectangle([x, y0 + 60, x + cw, y0 + 74], fill=RED)
        d.text((x + 6, y0 + 62), banner, font=SANS_B(11),
               fill=(255, 255, 255))
        # sentence-case news headline, two lines
        lines = wrap(d, head, SERIF_B(13), cw - 10)
        if len(lines) != 2:
            raise ValueError(f"hero {num}: headline wraps to "
                             f"{len(lines)} lines, expected 2")
        yy = y0 + 76
        for ln in lines:
            d.text((x + 5, yy), ln, font=SERIF_B(13), fill=INK)
            yy += 14
        # summary unchanged, three lines
        lines = wrap(d, summ, SANS(10), cw - 10)
        if len(lines) != 3:
            raise ValueError(f"hero {num}: summary wraps to "
                             f"{len(lines)} lines, expected 3")
        for ln in lines:
            d.text((x + 5, yy), ln, font=SANS(10), fill=INK)
            yy += 11
        d.text((x + 5, y0 + 152 - 13), f"({src})", font=SANS(9), fill=GREY)
        label_chip(d, x + cw - 62, y0 + 152 - 14, lab)

    # --- features 04-13: 5 cols x 2 rows, big illustration bands ---
    # Each card is 192 wide x 156 tall: a 190x64 illustration band on top
    # (larger than the top 3's medium bands), then headline, the FULL
    # four-line summary (never truncated), source + label. Headlines
    # shrink 11 -> 10 -> 9 pt until they wrap to two lines.
    fy = 364
    ch2 = 156
    fw2 = (W - 2 * M - 4 * 8) // 5
    for i, (num, reg, head, summ, src, lab) in enumerate(FEATURES):
        col_i, row_i = i % 5, i // 5
        x = M + col_i * (fw2 + 8)
        y = fy + row_i * (ch2 + 5)
        col = REG_COL[reg]
        d.rectangle([x, y, x + fw2, y + ch2], outline=LINE, width=1,
                    fill=CARD)
        draw_illus_layer(img, num, x + 1, y + 1, fw2 - 2, 64, big=True)
        header_chip(d, x + 4, y + 4, f"{num:02d} · {reg}", col)
        hfnt = fit_headline(d, head, fw2 - 10)
        yy = y + 66
        for ln in wrap(d, head, hfnt, fw2 - 10)[:2]:
            d.text((x + 5, yy), ln, font=hfnt, fill=INK)
            yy += 14
        yy = y + 96
        slines = wrap(d, summ, SANS(10), fw2 - 10)
        # Every summary wraps to exactly four lines at this width; render
        # all of them — never truncate, never add an ellipsis.
        if len(slines) != 4:
            raise ValueError(f"feature {num}: summary wraps to "
                             f"{len(slines)} lines, expected 4")
        for ln in slines:
            d.text((x + 5, yy), ln, font=SANS(10), fill=INK)
            yy += 12
        d.text((x + 5, y + 146), f"({src})", font=SANS(8), fill=GREY)
        label_chip(d, x + fw2 - 62, y + 145, lab)

    # --- third row: map (cols 1-2) + feature cards 14/15 (cols 3-4)
    # + DATE CHECK (col 5) ---
    # The map keeps one scale for both axes: MAP_S px per degree of
    # longitude AND latitude, so continents are true to shape. The
    # inner map keeps its v5 size (368x135, scale 368/350 deg) and is
    # centred in the two-column-wide box; the DATE CHECK box moves to
    # the fifth column, same height, narrower type (content unchanged).
    global MAP_S
    my0 = 686
    MAP_S = 368 / 350.0
    d.rectangle([M, my0, M + 2 * fw2 + 8, my0 + 156], outline=LINE, width=1,
                fill=OCEAN)
    d.text((M + 6, my0 + 4),
           "WHERE IT HAPPENED — the 11 located stories, numbered",
           font=SANS_B(11), fill=INK)
    mx0, my1, mw, mh = M + 12, my0 + 18, 368, 135
    # graticule every 30 deg lon / 20 deg lat, clear blue-grey on the
    # ocean (drawn before the land, so it never covers a coast or a pin)
    for lon in range(-150, 151, 30):
        gx, _ = project(lon, 0, mx0, my1, mw, mh)
        d.line([gx, my1, gx, my1 + mh], fill=GRAT, width=1)
    for lat in (60, 40, 20, 0, -20, -40):
        _, gy = project(0, lat, mx0, my1, mw, mh)
        d.line([mx0, gy, mx0 + mw, gy], fill=GRAT, width=1)
    for poly in CONTINENTS:
        pts = [project(lon, lat, mx0, my1, mw, mh) for lon, lat in poly]
        d.polygon(pts, fill=MAPLAND, outline=MAPLINE, width=2)
    # Big inland lakes, drawn as ocean over the land (before the pins,
    # so no pin is ever covered).
    for poly in LAKES:
        pts = [project(lon, lat, mx0, my1, mw, mh) for lon, lat in poly]
        d.polygon(pts, fill=OCEAN)
    # Pins: numbered, on their true lon/lat. In the Europe / Gulf
    # clusters the true positions are only a few px apart at this
    # scale, so those markers are nudged into a staggered grid, with
    # a leader line back to the true position.
    PIN_NUDGE = {7: (-9, -7), 13: (9, -7), 8: (-9, 9), 1: (9, 7),
                 2: (8, 8), 9: (8, -6)}
    for n, (lon, lat) in PINS.items():
        px, py = project(lon, lat, mx0, my1, mw, mh)
        dx, dy = PIN_NUDGE.get(n, (0, 0))
        ox, oy = px + dx, py + dy
        if (ox, oy) != (px, py):
            d.line([px, py, ox, oy], fill=(90, 82, 64), width=1)
        d.ellipse([ox - 7, oy - 7, ox + 7, oy + 7], fill=RED,
                  outline=(255, 255, 255), width=2)
        d.text((ox, oy - 4), str(n), font=SANS_B(8), fill=(255, 255, 255),
               anchor="ma")
    # feature cards 14 and 15, same shape as the other features
    for j, (num, reg, head, summ, src, lab) in enumerate(FEATURES3):
        x = M + (2 + j) * (fw2 + 8)
        y = my0
        col = REG_COL[reg]
        d.rectangle([x, y, x + fw2, y + ch2], outline=LINE, width=1,
                    fill=CARD)
        draw_illus_layer(img, num, x + 1, y + 1, fw2 - 2, 64, big=True)
        header_chip(d, x + 4, y + 4, f"{num:02d} · {reg}", col)
        hfnt = fit_headline(d, head, fw2 - 10)
        yy = y + 66
        for ln in wrap(d, head, hfnt, fw2 - 10)[:2]:
            d.text((x + 5, yy), ln, font=hfnt, fill=INK)
            yy += 14
        yy = y + 96
        slines = wrap(d, summ, SANS(10), fw2 - 10)
        if len(slines) != 4:
            raise ValueError(f"feature {num}: summary wraps to "
                             f"{len(slines)} lines, expected 4")
        for ln in slines:
            d.text((x + 5, yy), ln, font=SANS(10), fill=INK)
            yy += 12
        d.text((x + 5, y + 146), f"({src})", font=SANS(8), fill=GREY)
        label_chip(d, x + fw2 - 62, y + 145, lab)
    # DATE CHECK box, one column wide: same text, smaller type so it
    # fits the narrow box (title 9 pt, body 11 pt, 8 lines)
    dx0 = M + 4 * (fw2 + 8)
    d.rectangle([dx0, my0, W - M, my0 + 156], outline=RED, width=2,
                fill=(255, 240, 235))
    d.text((dx0 + 6, my0 + 10), "DATE CHECK — NOT 21 NOVEMBER",
           font=SANS_B(9), fill=RED)
    for j, ln in enumerate(wrap(d, DATE_CHECK, SANS(11), W - M - dx0 - 12)):
        d.text((dx0 + 6, my0 + 28 + j * 14), ln, font=SANS(11), fill=INK)

    # --- how we checked ---
    d.text((M, 846),
           "HOW WE CHECKED:  CONFIRMED verified  ·  OFFICIAL stated by an "
           "authority  ·  REPORTED not yet verified  ·  CLAIM one side's "
           "claim  ·  FORECAST still to happen",
           font=SANS(10), fill=GREY)

    # --- briefs 16-35: 2 cols x 10 rows (14/15 are feature cards now) ---
    by = 858
    d.text((M, by), "THE REST OF THE DAY — briefs 16–35", font=SANS_B(12),
           fill=INK)
    by += 12
    brh = 11
    bw2 = (W - 2 * M - 10) // 2
    for i, (num, reg, text, src, lab) in enumerate(BRIEFS):
        col_i, row_i = i % 2, i // 2
        x = M + col_i * (bw2 + 10)
        y = by + row_i * brh
        d.text((x, y), f"{num}.", font=SANS_B(11), fill=REG_COL[reg])
        full = f"{text} ({src}) [{lab}]"
        fnt = fit_font(d, full, "DejaVuSans.ttf", 9, bw2 - 26)
        d.text((x + 24, y), full, font=fnt, fill=INK)

    # --- footer ---
    fy2 = by + ((len(BRIEFS) + 1) // 2) * brh + 2
    d.line([M, fy2, W - M, fy2], fill=LINE, width=1)
    d.text((M, fy2 + 4),
           "Sources: AP, Reuters, USGS, CAAP, Finnhub, IANS, ESA, NBC, "
           "Al Jazeera, IRIB, Saudi Press Agency, UN News, F1, KCNA, Yonhap, "
           "CNA, PTI, IMD, CBC, AAP, h.ua, make.fun — named per story.",
           font=SANS(9), fill=GREY)
    d.text((M, fy2 + 16),
           "All 35 stories happened or were first reported on Saturday 21 "
           "November 2026. Story 7 is a scheduled event; story 9 and story 14 "
           "are claims, not confirmed facts.",
           font=SANS(9), fill=GREY)
    img.save("entry.png", optimize=True)


if __name__ == "__main__":
    main()
    print("wrote entry.png")
